PREFIX dbo: <http://dbpedia.org/ontology/>
PREFIX dbp: <http://dbpedia.org/property/>
PREFIX dbr: <http://dbpedia.org/resource/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?earlierFilm ?earlierFilmLabel ?earlierDirector ?earlierDirectorLabel ?earlierBirthDate ?otherFilm ?otherBirthDate WHERE {
  BIND(dbr:Get_Yourself_a_College_Girl AS ?film1)
  BIND(dbr:Jesse_James_at_Bay AS ?film2)

  OPTIONAL { ?film1 dbo:director ?d1. }
  OPTIONAL { ?film1 dbp:director ?d1_2. }
  BIND(coalesce(?d1, ?d1_2) AS ?dir1)

  OPTIONAL { ?film2 dbo:director ?d2. }
  OPTIONAL { ?film2 dbp:director ?d2_2. }
  BIND(coalesce(?d2, ?d2_2) AS ?dir2)

  OPTIONAL { ?dir1 dbo:birthDate ?bd1. }
  OPTIONAL { ?dir1 dbp:birthDate ?bd1_2. }
  OPTIONAL { ?dir1 dbp:birth_date ?bd1_3. }
  BIND(coalesce(?bd1, ?bd1_2, ?bd1_3) AS ?birth1)

  OPTIONAL { ?dir2 dbo:birthDate ?bd2. }
  OPTIONAL { ?dir2 dbp:birthDate ?bd2_2. }
  OPTIONAL { ?dir2 dbp:birth_date ?bd2_3. }
  BIND(coalesce(?bd2, ?bd2_2, ?bd2_3) AS ?birth2)

  {
    FILTER(bound(?birth1) && bound(?birth2) && ?birth1 < ?birth2)
    BIND(?film1 AS ?earlierFilm)
    BIND(?dir1 AS ?earlierDirector)
    BIND(?birth1 AS ?earlierBirthDate)
    BIND(?film2 AS ?otherFilm)
    BIND(?birth2 AS ?otherBirthDate)
  } UNION {
    FILTER(bound(?birth1) && bound(?birth2) && ?birth2 < ?birth1)
    BIND(?film2 AS ?earlierFilm)
    BIND(?dir2 AS ?earlierDirector)
    BIND(?birth2 AS ?earlierBirthDate)
    BIND(?film1 AS ?otherFilm)
    BIND(?birth1 AS ?otherBirthDate)
  }

  OPTIONAL { ?earlierFilm rdfs:label ?earlierFilmLabel . FILTER(langMatches(lang(?earlierFilmLabel),"EN")) }
  OPTIONAL { ?earlierDirector rdfs:label ?earlierDirectorLabel . FILTER(langMatches(lang(?earlierDirectorLabel),"EN")) }
}

